import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BaohFyeo.js";const u=JSON.parse('{"title":"Migration","description":"What it takes to replace another Markdown editor with Mawy, and what happens to the documents you already have.","frontmatter":{"title":"Migration","order":3},"headers":[],"relativePath":"migrate/index.md","filePath":"en/migrate/index.md","lastUpdated":1789966012000}'),i={name:"migrate/index.md"};function n(d,e,s,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="moving-from-another-editor" tabindex="-1">Moving from another editor <a class="header-anchor" href="#moving-from-another-editor" aria-label="Permalink to &quot;Moving from another editor&quot;">​</a></h1><p>What it takes to replace another Markdown editor with Mawy, and what happens to the documents you already have.</p><p>Every editor here stores the same thing in the end: a Markdown string in a column somewhere. Mawy takes that string as <code>value</code> and hands it back through <code>onChange</code>, so most of a migration is wiring rather than conversion — where the string comes from, where it goes, and which of your old options have a name here.</p><table tabindex="0"><thead><tr><th>Coming from</th><th>Package</th><th>Page</th></tr></thead><tbody><tr><td>Toast UI Editor</td><td><code>@toast-ui/editor</code>, <code>@toast-ui/react-editor</code></td><td><a href="./toast-ui-editor">From Toast UI Editor</a></td></tr><tr><td>MDXEditor</td><td><code>@mdxeditor/editor</code></td><td><a href="./mdxeditor">From MDXEditor</a></td></tr><tr><td>Milkdown</td><td><code>@milkdown/kit</code>, <code>@milkdown/crepe</code></td><td><a href="./milkdown">From Milkdown</a></td></tr><tr><td>react-md-editor</td><td><code>@uiw/react-md-editor</code></td><td><a href="./react-md-editor">From react-md-editor</a></td></tr></tbody></table><div class="mawy-fw" data-fw="flutter"><p>These are all web libraries, so there is nothing to migrate from inside a Flutter application. This section is useful here for one case: an application whose documents are written in a browser and read in an app. The parser is the same in both packages and a check diffs the two on every change, so a document moved off one of these editors reads the same on a phone as it does on the page it was written on.</p></div><h2 id="the-shape-of-all-four" tabindex="-1">The shape of all four <a class="header-anchor" href="#the-shape-of-all-four" aria-label="Permalink to &quot;The shape of all four&quot;">​</a></h2><ol><li><strong>Put <code>MawyEditor</code> where the old editor was</strong>, with <code>value</code> and <code>onChange</code> instead of an instance and a ref. See <a href="./../guide/editor">the editor</a>.</li><li><strong>Replace whatever renders a finished document</strong> with <a href="./../api/components/mawy-viewer"><code>MawyViewer</code></a>, or with <a href="./../api/components/mawy-document"><code>MawyDocument</code></a> on a page that should ship no JavaScript. Most applications have one of these and forget it is there.</li><li><strong>Import <code>mawy-react/styles.css</code> once</strong> and delete the old editor&#39;s stylesheets. Your overrides of its class names go with them; theming here is <a href="./../api/theming">redeclaring a <code>--mawy-*</code> token</a>.</li><li><strong>Translate the options</strong> using the table on your editor&#39;s page. Most have a name here; the ones that do not are listed rather than left for you to find.</li><li><strong>Open a few real documents and save them unchanged</strong>, then diff. This is where an editor that rewrites documents shows itself, and it is worth doing before the old editor comes out.</li></ol><h2 id="what-it-does-to-your-documents" tabindex="-1">What it does to your documents <a class="header-anchor" href="#what-it-does-to-your-documents" aria-label="Permalink to &quot;What it does to your documents&quot;">​</a></h2><p><strong>Nothing.</strong> Mawy edits the Markdown string itself, so a document that opens unchanged saves unchanged: the same list markers, the same emphasis characters, the same blank lines. There is no serialiser in the package to normalise anything, and switching between the source and the drawn document mounts a different surface rather than converting the file.</p><p>What has already happened to your documents is a different question. An editor that holds a model and writes Markdown out of it rewrote each document as it was saved, and those documents are in your database in the shape that editor left them. They still read the same, and they are still valid Markdown; they simply are not the text their authors typed. Nothing here can undo that, and nothing here will do it again.</p><h2 id="an-editor-that-is-not-on-this-list" tabindex="-1">An editor that is not on this list <a class="header-anchor" href="#an-editor-that-is-not-on-this-list" aria-label="Permalink to &quot;An editor that is not on this list&quot;">​</a></h2><p>The five steps above are the whole recipe, and the pages differ only in the mapping tables. Two things are worth checking for an editor that is not here:</p><ul><li><strong>Whether it stores Markdown at all.</strong> An editor that stores its own JSON — a ProseMirror document, a Lexical state, BlockNote&#39;s blocks — has to export Markdown once, for every row, with its own exporter. Do that while the old editor is still installed, because after it goes the only thing that can read those rows is gone.</li><li><strong>What its export does to a document.</strong> Run a handful of real documents through it and read the output. BlockNote&#39;s method is called <code>blocksToMarkdownLossy</code> for a reason, and a one-way conversion is worth knowing the cost of before it is the only copy you have.</li></ul>',13)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
